using Godot;
using System;
using System.Collections.Generic;
using System.Linq;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class PhysicsGeometryOperations
{
    public Settings particles(Settings geometry,int count,Transform3D pose)
    {
        var source=geometry["points"].AsVector3Array();if(source.Length>30000)return new Settings{["error"]="Deformation supports up to 30,000 render vertices per actor. Use a lower-resolution simulation model."};var unique=new Settings();foreach(var point in source)unique[point.Snapped(Vector3.One*.0001f)]=point;var values=unique.Values.ToArray();int stride=Math.Max(1,(int)Math.Ceiling((double)values.Length/Math.Clamp(count,8,256)));var local=new List<Vector3>();for(int i=0;i<values.Length;i+=stride)local.Add(values[i].AsVector3());if(local.Count<3)return new Settings{["error"]="This actor needs a triangle mesh with at least three distinct vertices."};var points=local.Select(point=>pose*point).ToArray();var links=new Settings();var bindings=new GArray();foreach(var value in geometry["meshes"].AsGodotArray()){var item=value.AsGodotDictionary();var surfaces=new GArray();var transform=item["local"].AsTransform3D();foreach(var surface in item["surfaces"].AsGodotArray()){var arrays=surface.AsGodotArray();var vertices=arrays[(int)Mesh.ArrayType.Vertex].AsVector3Array();var ids=new GArray();var weights=new GArray();var rest=new Vector3[vertices.Length];for(int vertex=0;vertex<vertices.Length;vertex++){var point=transform*vertices[vertex];var nearest=new[]{-1,-1,-1};var distances=new[]{double.PositiveInfinity,double.PositiveInfinity,double.PositiveInfinity};for(int i=0;i<local.Count;i++){double distance=point.DistanceSquaredTo(local[i]);for(int slot=0;slot<3;slot++){if(distance>=distances[slot])continue;for(int shift=2;shift>slot;shift--){distances[shift]=distances[shift-1];nearest[shift]=nearest[shift-1];}distances[slot]=distance;nearest[slot]=i;break;}}var weight=new Vector3((float)(1/Math.Max(.0000001,distances[0])),(float)(1/Math.Max(.0000001,distances[1])),(float)(1/Math.Max(.0000001,distances[2])));weight/=weight.X+weight.Y+weight.Z;ids.Add(new Vector3I(nearest[0],nearest[1],nearest[2]));weights.Add(weight);rest[vertex]=pose*point;}var indices=arrays[(int)Mesh.ArrayType.Index].VariantType==Variant.Type.Nil?Array.Empty<int>():arrays[(int)Mesh.ArrayType.Index].AsInt32Array();int n=indices.Length>0?indices.Length:vertices.Length;for(int triangle=0;triangle<n-2;triangle+=3)for(int edge=0;edge<3;edge++){int a=ids[indices.Length>0?indices[triangle+edge]:triangle+edge].AsVector3I().X,b=ids[indices.Length>0?indices[triangle+(edge+1)%3]:triangle+(edge+1)%3].AsVector3I().X;if(a!=b)links[new Vector2I(Math.Min(a,b),Math.Max(a,b))]=true;}surfaces.Add(new Settings{["ids"]=ids,["weights"]=weights,["rest"]=rest});}bindings.Add(new Settings{["item"]=item,["surfaces"]=surfaces});}
        var edges=new GArray();var neighbours=new Settings();foreach(var key in links.Keys){var pair=key.AsVector2I();edges.Add(new GArray{pair.X,pair.Y,points[pair.X].DistanceTo(points[pair.Y]),false});if(!neighbours.ContainsKey(pair.X))neighbours[pair.X]=new GArray();if(!neighbours.ContainsKey(pair.Y))neighbours[pair.Y]=new GArray();neighbours[pair.X].AsGodotArray().Add(pair.Y);neighbours[pair.Y].AsGodotArray().Add(pair.X);}foreach(var center in neighbours.Keys){var adjacent=neighbours[center].AsGodotArray();for(int i=0;i<adjacent.Count;i++)for(int j=i+1;j<adjacent.Count;j++){int a=adjacent[i].AsInt32(),b=adjacent[j].AsInt32();var pair=new Vector2I(Math.Min(a,b),Math.Max(a,b));if(links.ContainsKey(pair))continue;links[pair]=true;edges.Add(new GArray{pair.X,pair.Y,points[pair.X].DistanceTo(points[pair.Y]),true});}}return new Settings{["error"]="",["local"]=local.ToArray(),["rest"]=points,["edges"]=edges,["bindings"]=bindings};
    }
    public void deform(Settings data,Vector3[] points,double influence)
    {
        var rest=data["rest"].AsVector3Array();foreach(var value in data["bindings"].AsGodotArray()){var binding=value.AsGodotDictionary();var item=binding["item"].AsGodotDictionary();var node=item["node"].AsGodotObject() as MeshInstance3D;if(!GodotObject.IsInstanceValid(node))continue;var mesh=new ArrayMesh();mesh.SetMeta("kiwi_physics_mesh",true);var transform=node!.GlobalTransform;var inverse=transform.AffineInverse();var surfaces=item["surfaces"].AsGodotArray();var mappings=binding["surfaces"].AsGodotArray();for(int surface=0;surface<surfaces.Count;surface++){var arrays=surfaces[surface].AsGodotArray().Duplicate(true);var source=arrays[(int)Mesh.ArrayType.Vertex].AsVector3Array();var mapping=mappings[surface].AsGodotDictionary();var ids=mapping["ids"].AsGodotArray();var weights=mapping["weights"].AsGodotArray();var target=mapping["rest"].AsVector3Array();var positions=new Vector3[source.Length];for(int i=0;i<source.Length;i++){var indices=ids[i].AsVector3I();var weight=weights[i].AsVector3();var delta=(points[indices.X]-rest[indices.X])*weight.X+(points[indices.Y]-rest[indices.Y])*weight.Y+(points[indices.Z]-rest[indices.Z])*weight.Z;positions[i]=inverse*(transform*source[i]).Lerp(target[i]+delta,(float)influence);}arrays[(int)Mesh.ArrayType.Vertex]=positions;var normals=new Vector3[positions.Length];var indicesArray=arrays[(int)Mesh.ArrayType.Index].VariantType==Variant.Type.Nil?Array.Empty<int>():arrays[(int)Mesh.ArrayType.Index].AsInt32Array();int count=indicesArray.Length>0?indicesArray.Length:positions.Length;for(int i=0;i<count-2;i+=3){int a=indicesArray.Length>0?indicesArray[i]:i,b=indicesArray.Length>0?indicesArray[i+1]:i+1,c=indicesArray.Length>0?indicesArray[i+2]:i+2;var normal=(positions[b]-positions[a]).Cross(positions[c]-positions[a]).Normalized();normals[a]+=normal;normals[b]+=normal;normals[c]+=normal;}for(int i=0;i<normals.Length;i++)normals[i]=normals[i].Normalized();arrays[(int)Mesh.ArrayType.Normal]=normals;arrays[(int)Mesh.ArrayType.Tangent]=default;arrays[(int)Mesh.ArrayType.Bones]=default;arrays[(int)Mesh.ArrayType.Weights]=default;mesh.AddSurfaceFromArrays(Mesh.PrimitiveType.Triangles,arrays);mesh.SurfaceSetMaterial(surface,item["materials"].AsGodotArray()[surface].As<Material>());}node.Mesh=mesh;node.Skin=null;}
    }
    public ArrayMesh rope_mesh(Vector3[] points,Transform3D inverse,double radius,Material? material)
    {
        const int sides=8;var vertices=new Vector3[points.Length*sides];var normals=new Vector3[vertices.Length];var uvs=new Vector2[vertices.Length];var indices=new List<int>();for(int i=0;i<points.Length;i++){var tangent=(points[Math.Min(i+1,points.Length-1)]-points[Math.Max(0,i-1)]).Normalized();var axis=tangent.Cross(Math.Abs(tangent.Dot(Vector3.Up))<.95?Vector3.Up:Vector3.Right).Normalized();var other=tangent.Cross(axis).Normalized();for(int j=0;j<sides;j++){var normal=axis*Mathf.Cos(Mathf.Tau*j/sides)+other*Mathf.Sin(Mathf.Tau*j/sides);int index=i*sides+j;vertices[index]=inverse*(points[i]+normal*(float)radius);normals[index]=inverse.Basis*normal;uvs[index]=new Vector2((float)j/sides,(float)i/Math.Max(1,points.Length-1));}if(i>0)for(int j=0;j<sides;j++){int a=(i-1)*sides+j,b=(i-1)*sides+(j+1)%sides,c=i*sides+j,d=i*sides+(j+1)%sides;indices.AddRange(new[]{a,c,b,b,c,d});}}var arrays=new GArray();arrays.Resize((int)Mesh.ArrayType.Max);arrays[(int)Mesh.ArrayType.Vertex]=vertices;arrays[(int)Mesh.ArrayType.Normal]=normals;arrays[(int)Mesh.ArrayType.TexUV]=uvs;arrays[(int)Mesh.ArrayType.Index]=indices.ToArray();var mesh=new ArrayMesh();mesh.AddSurfaceFromArrays(Mesh.PrimitiveType.Triangles,arrays);mesh.SurfaceSetMaterial(0,material);return mesh;
    }
}
